use vstd::prelude::*;

verus! {

    /// Given a fixed‐length array `arr` of 10 booleans,
    /// build and return a dynamic Vec<bool> of length 10
    /// such that for every index k in [0,10),
    /// the returned vector’s element at k equals `arr[k]`.
    fn array_to_sequence(arr: &[bool; 10]) -> Vec<bool>
        ensures
            // the result has length 10
            ret.len() == 10 &&
            // it exactly copies the input array
            forall |k: usize| k < 10 ==> ret[k] == arr[k]
    {
        // Start with an empty vector
        let mut ret: Vec<bool> = Vec::new();

        // We will iterate from i = 0 .. 10, pushing arr[i] at each step.
        let mut i: usize = 0;
        while i < 10 {
            // Loop invariants to help the verifier:
            // 1) 0 <= i <= 10
            invariant i <= 10;
            // 2) we've pushed exactly i elements so far
            invariant ret.len() == i;
            // 3) for all j < i, ret[j] == arr[j]
            invariant forall |j: usize| j < i ==> ret[j] == arr[j];
            // 4) the loop will terminate because i increases
            decreases 10 - i;

            // Push the next element
            ret.push(arr[i]);
            i += 1;
        }

        // At this point i == 10, so by the invariants:
        //  ret.len() == 10
        //  forall j < 10, ret[j] == arr[j]
        ret
    }
}